import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { formatDate, formatMoney, fromCents, scopeLabel, toCents } from "@/lib/finance";
import { ImportColumn, inferImportMapping, inferImportType, parseImportAmount, parseImportDate, parseSpreadsheet, SpreadsheetRow } from "@/lib/importSpreadsheet";
import { createImportTemplateCsv, importTemplateFilename } from "@/lib/importTemplate";
import { trpc } from "@/lib/trpc";
import { emptyWorkspaceFilters, filterWorkspaceSnapshot, WorkspaceFilterBar } from "@/components/WorkspaceFilterBar";
import { Archive, ArrowDownLeft, ArrowLeftRight, ArrowUpRight, Building2, CreditCard, FileText, FolderPlus, Landmark, Pencil, Plus, ReceiptText, Trash2, Upload, WalletCards } from "lucide-react";
import { FormEvent, useMemo, useState } from "react";
import { toast } from "sonner";
import { Link } from "wouter";

type RecordMode = "movement" | "transfer" | "account" | "category" | "document";

const typeLabel = {
  income: "Ingreso",
  expense: "Gasto",
  transfer_out: "Transferencia salida",
  transfer_in: "Transferencia entrada",
} as const;

function ScopePill({ scope }: { scope: "personal" | "business" | "mixed" }) {
  return <span className={`scope-pill scope-${scope}`}>{scopeLabel[scope]}</span>;
}

function ImportTransactionsDialog({ open, onOpenChange, snapshot, onDone }: { open: boolean; onOpenChange: (open: boolean) => void; snapshot: any; onDone: () => void }) {
  const [headers, setHeaders] = useState<string[]>([]); const [rawRows, setRawRows] = useState<SpreadsheetRow[]>([]); const [mapping, setMapping] = useState<Partial<Record<ImportColumn, string>>>({}); const [accountId, setAccountId] = useState(""); const [categoryId, setCategoryId] = useState(""); const [entityId, setEntityId] = useState(""); const [projectId, setProjectId] = useState(""); const [scope, setScope] = useState("personal"); const [currency, setCurrency] = useState(snapshot.profile?.currency || "MXN"); const [previewRows, setPreviewRows] = useState<any[]>([]); const [accepted, setAccepted] = useState<Set<number>>(new Set());
  const preview = trpc.finance.workspace.imports.preview.useMutation({ onSuccess: rows => { setPreviewRows(rows); setAccepted(new Set(rows.filter(row => row.possibleDuplicateIds.length === 0).map(row => row.index))); }, onError: error => toast.error(error.message) });
  const confirmImport = trpc.finance.workspace.imports.confirm.useMutation({ onSuccess: result => { toast.success(`${result.importedCount} filas importadas tras tu confirmación`); onDone(); onOpenChange(false); }, onError: error => toast.error(error.message) });
  const buildRows = () => rawRows.slice(0, 300).map((row, index) => { const occurredAt = parseImportDate(mapping.date ? row[mapping.date] : null); const amountCents = parseImportAmount(mapping.amount ? row[mapping.amount] : null); if (!occurredAt || !amountCents) throw new Error(`La fila ${index + 2} necesita fecha e importe válidos.`); const rawCurrency = mapping.currency ? String(row[mapping.currency] ?? "").trim().toUpperCase() : currency; return { accountId: accountId ? Number(accountId) : null, categoryId: categoryId ? Number(categoryId) : null, entityId: entityId ? Number(entityId) : null, projectId: projectId ? Number(projectId) : null, type: inferImportType(row, mapping), scope: scope as any, amountCents, currency: (rawCurrency || currency).slice(0, 3), reportCurrency: (rawCurrency || currency).slice(0, 3), reportAmountCents: amountCents, exchangeRateMicros: null, exchangeRateDate: null, incomeNature: "other" as const, occurredAt: occurredAt.getTime(), isEssential: false, status: "confirmed" as const, notes: mapping.description ? String(row[mapping.description] ?? "").trim() || `Importación fila ${index + 2}` : `Importación fila ${index + 2}`, allowPossibleDuplicate: false }; });
  const loadFile = async (file?: File) => { if (!file) return; try { const parsed = await parseSpreadsheet(file); if (!parsed.rows.length) throw new Error("El archivo no contiene filas de datos."); setHeaders(parsed.headers); setRawRows(parsed.rows.slice(0, 300)); setMapping(inferImportMapping(parsed.headers)); setPreviewRows([]); setAccepted(new Set()); } catch (error) { toast.error(error instanceof Error ? error.message : "No fue posible leer el archivo."); } };
  const runPreview = () => { try { preview.mutate({ rows: buildRows() }); } catch (error) { toast.error(error instanceof Error ? error.message : "Revisa el mapeo antes de continuar."); } };
  const commit = () => { const rows = previewRows.filter(row => accepted.has(row.index)).map(row => ({ ...row.row, allowPossibleDuplicate: row.possibleDuplicateIds.length > 0 })); if (!rows.length) return toast.error("Selecciona al menos una fila para confirmar la importación."); confirmImport.mutate({ rows }); };
  const options = (key: ImportColumn, label: string, required = false) => <div className="form-field"><Label>{label}</Label><select value={mapping[key] || ""} onChange={event => setMapping({ ...mapping, [key]: event.target.value || undefined })}><option value="">{required ? "Selecciona una columna" : "No disponible"}</option>{headers.map(header => <option key={header} value={header}>{header}</option>)}</select></div>;
  const downloadTemplate = () => { const url = URL.createObjectURL(new Blob(["\ufeff" + createImportTemplateCsv()], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = importTemplateFilename; link.click(); URL.revokeObjectURL(url); };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Importar CSV o Excel</DialogTitle><DialogDescription>El archivo se procesa localmente para revisión y no se conserva. Nada se guarda hasta que confirmes las filas seleccionadas.</DialogDescription></DialogHeader><div className="form-grid"><div className="form-field span-2"><div className="flex flex-col gap-2 rounded-xl border border-dashed p-3 sm:flex-row sm:items-center sm:justify-between"><div><Label>Plantilla compatible</Label><p className="mt-1 text-xs text-muted-foreground">Columnas: Fecha, Descripción, Importe, Tipo y Moneda. Usa Ingreso o Gasto.</p></div><Button type="button" variant="outline" size="sm" onClick={downloadTemplate}>Descargar CSV</Button></div></div><div className="form-field span-2"><Label>Archivo CSV, XLSX o XLS</Label><Input type="file" accept=".csv,.xlsx,.xls" onChange={event => loadFile(event.target.files?.[0])} /><small>Máximo 300 filas por importación. Revisa el mapeo antes de confirmar.</small></div>{rawRows.length ? <><div className="form-field span-2"><div className="rounded-xl border border-primary/15 bg-primary/5 p-3 text-sm text-muted-foreground">{rawRows.length} filas cargadas localmente. Asigna las columnas y el contexto común; puedes revisar duplicados antes de guardar.</div></div>{options("date", "Columna de fecha", true)}{options("amount", "Columna de importe", true)}{options("description", "Columna de detalle")}{options("type", "Columna de tipo")}{options("currency", "Columna de moneda")}<div className="form-field"><Label>Cuenta común</Label><select value={accountId} onChange={event => setAccountId(event.target.value)}><option value="">Sin cuenta</option>{snapshot.accounts.map((account: any) => <option key={account.id} value={account.id}>{account.name}</option>)}</select></div><div className="form-field"><Label>Categoría común</Label><select value={categoryId} onChange={event => setCategoryId(event.target.value)}><option value="">Sin categoría</option>{snapshot.categories.filter((category: any) => category.isActive).map((category: any) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></div><div className="form-field"><Label>Entidad común</Label><select value={entityId} onChange={event => { setEntityId(event.target.value); setProjectId(""); }}><option value="">Sin entidad / personal</option>{snapshot.entities.map((entity: any) => <option key={entity.id} value={entity.id}>{entity.shortCode || entity.name}</option>)}</select></div><div className="form-field"><Label>Proyecto común</Label><select value={projectId} onChange={event => setProjectId(event.target.value)}><option value="">Sin proyecto</option>{snapshot.projects.filter((project: any) => !entityId || project.entityId === Number(entityId)).map((project: any) => <option key={project.id} value={project.id}>{project.name}</option>)}</select></div><div className="form-field"><Label>Ámbito</Label><select value={scope} onChange={event => setScope(event.target.value)}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><div className="form-field"><Label>Moneda si falta</Label><Input maxLength={3} value={currency} onChange={event => setCurrency(event.target.value.toUpperCase())} /></div><div className="form-actions span-2"><Button type="button" onClick={runPreview} disabled={preview.isPending}>{preview.isPending ? "Analizando…" : "Previsualizar y revisar"}</Button></div></> : null}</div>{previewRows.length ? <div className="mt-5 space-y-2"><h3 className="font-semibold">Confirmación de filas</h3><p className="text-sm text-muted-foreground">Las coincidencias se excluyen inicialmente. Márcalas sólo si confirmas que no son un duplicado.</p><div className="max-h-72 overflow-auto rounded-xl border"><table><thead><tr><th>Incluir</th><th>Fecha</th><th>Detalle</th><th>Importe</th><th>Revisión</th></tr></thead><tbody>{previewRows.map(row => <tr key={row.index}><td><input aria-label={`Incluir fila ${row.index + 2}`} type="checkbox" checked={accepted.has(row.index)} onChange={event => setAccepted(current => { const next = new Set(current); event.target.checked ? next.add(row.index) : next.delete(row.index); return next; })} /></td><td>{formatDate(new Date(row.row.occurredAt))}</td><td>{row.row.notes}</td><td>{formatMoney(row.row.amountCents, row.row.currency)}</td><td>{row.possibleDuplicateIds.length ? `Posible duplicado #${row.possibleDuplicateIds.join(", #")}` : "Sin coincidencia"}</td></tr>)}</tbody></table></div><div className="form-actions"><Button type="button" onClick={commit} disabled={confirmImport.isPending}>{confirmImport.isPending ? "Guardando…" : "Confirmar filas seleccionadas"}</Button></div></div> : null}</DialogContent></Dialog>;
}

export default function Records() {
  const utils = trpc.useUtils();
  const { data, isLoading } = trpc.finance.dashboard.useQuery();
  const [mode, setMode] = useState<RecordMode>("movement");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingMovement, setEditingMovement] = useState<any>(null);
  const [editingTransfer, setEditingTransfer] = useState<any>(null);
  const [editingAccount, setEditingAccount] = useState<any>(null);
  const [editingCategory, setEditingCategory] = useState<any>(null);
  const [editingDocument, setEditingDocument] = useState<any>(null);
  const [initialMovementType, setInitialMovementType] = useState<keyof typeof typeLabel>("expense");
  const [workspaceFilters, setWorkspaceFilters] = useState(emptyWorkspaceFilters);
  const [importOpen, setImportOpen] = useState(false);

  const refresh = async () => {
    await utils.finance.dashboard.invalidate();
    setDialogOpen(false);
    setEditingMovement(null);
    setEditingTransfer(null);
    setEditingAccount(null);
    setEditingCategory(null);
    setEditingDocument(null);
  };

  const removeTransaction = trpc.finance.transactions.remove.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) });
  const removeTransfer = trpc.finance.workspace.transferRemove.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) });
  const removeAccount = trpc.finance.accounts.remove.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) });
  const removeCategory = trpc.finance.categories.remove.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) });
  const removeDocument = trpc.finance.documents.remove.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) });

  const scopedData = useMemo<typeof data>(() => data ? filterWorkspaceSnapshot(data, workspaceFilters) : undefined, [data, workspaceFilters]);
  const accounts = scopedData?.accounts ?? [];
  const categories = data?.categories ?? [];
  const transactions = useMemo(() => (scopedData?.transactions ?? []).slice().sort((a, b) => new Date(b.occurredAt).getTime() - new Date(a.occurredAt).getTime()), [scopedData?.transactions]);

  const openCreate = (nextMode: RecordMode, movementType: keyof typeof typeLabel = "expense") => {
    setMode(nextMode);
    setInitialMovementType(movementType);
    setEditingMovement(null);
    setEditingTransfer(null);
    setEditingAccount(null);
    setEditingCategory(null);
    setEditingDocument(null);
    setDialogOpen(true);
  };

  if (isLoading) return <div className="page-loading">Cargando tus registros privados…</div>;

  return (
    <div className="space-y-8">
      <header className="page-heading">
        <div>
          <p className="eyebrow">Registro manual</p>
          <h1>Movimientos y recursos</h1>
          <p>Registra información confirmada, estimada o pendiente de revisar. Meximoney no conecta cuentas ni mueve dinero.</p>
        </div>
        {data ? <ImportTransactionsDialog open={importOpen} onOpenChange={setImportOpen} snapshot={data} onDone={refresh} /> : null}
        <Button variant="outline" onClick={() => setImportOpen(true)}><Upload className="size-4" /> Importar CSV/Excel</Button>
        <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
          <DialogTrigger asChild>
            <Button className="btn-primary" onClick={() => openCreate("movement")}><Plus className="size-4" /> Nuevo registro</Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>{editingMovement ? "Editar movimiento" : editingTransfer ? "Editar traspaso" : editingAccount ? "Editar cuenta o activo" : editingCategory ? "Editar categoría" : editingDocument ? "Editar documento" : "Crear un registro"}</DialogTitle>
              <DialogDescription>Los cambios solo afectan tus registros manuales de Meximoney.</DialogDescription>
            </DialogHeader>
            <Tabs value={mode} onValueChange={value => setMode(value as RecordMode)}>
              <TabsList className="grid grid-cols-5 w-full">
                <TabsTrigger value="movement">Movimiento</TabsTrigger>
                <TabsTrigger value="transfer">Traspaso</TabsTrigger>
                <TabsTrigger value="account">Cuenta</TabsTrigger>
                <TabsTrigger value="category">Categoría</TabsTrigger>
                <TabsTrigger value="document">Documento</TabsTrigger>
              </TabsList>
            </Tabs>
            {mode === "movement" && <MovementForm key={editingMovement ? `movement-${editingMovement.id}` : `new-movement-${initialMovementType}`} accounts={accounts} creditCards={data?.creditCards ?? []} categories={categories} contacts={data?.contacts ?? []} entities={data?.entities ?? []} projects={data?.projects ?? []} workspaceAccess={data?.workspaceAccess} defaultCurrency={data?.profile?.currency ?? "MXN"} initialType={initialMovementType} editing={editingMovement} onDone={refresh} />}
            {mode === "transfer" && <TransferForm key={editingTransfer ? `transfer-${editingTransfer.transferGroupId}` : "new-transfer"} accounts={accounts} investments={data?.investments ?? []} workspaceAccess={data?.workspaceAccess} editing={editingTransfer} onDone={refresh} />}
            {mode === "account" && <AccountForm key={editingAccount ? `account-${editingAccount.id}` : "new-account"} entities={data?.entities ?? []} projects={data?.projects ?? []} defaultCurrency={data?.profile?.currency ?? "MXN"} editing={editingAccount} onDone={refresh} />}
            {mode === "category" && <CategoryForm key={editingCategory ? `category-${editingCategory.id}` : "new-category"} editing={editingCategory} onDone={refresh} />}
            {mode === "document" && <DocumentForm key={editingDocument ? `document-${editingDocument.id}` : "new-document"} accounts={accounts} debts={data?.debts ?? []} entities={data?.entities ?? []} projects={data?.projects ?? []} editing={editingDocument} onDone={refresh} />}
          </DialogContent>
        </Dialog>
      </header>

      <section className="record-shortcuts" aria-label="Crear registros">
        {[
          { mode: "movement" as const, movementType: "income" as const, icon: ArrowDownLeft, title: "Ingreso", note: "Cobros y entradas manuales" },
          { mode: "movement" as const, movementType: "expense" as const, icon: ArrowUpRight, title: "Gasto", note: "Pagos y salidas manuales" },
          { mode: "transfer" as const, icon: ArrowLeftRight, title: "Traspaso", note: "Entre cuentas propias, no es ingreso" },
          { mode: "account" as const, icon: WalletCards, title: "Cuenta o activo", note: "Efectivo, banco, inversión o empresa" },
          { href: "/tarjetas", icon: CreditCard, title: "Tarjeta de crédito", note: "Saldo, corte, pago y gastos con TDC" },
          { mode: "document" as const, icon: FileText, title: "Documento", note: "Enlace de respaldo y vencimientos" },
        ].map(item => (
          "href" in item ? <Link key={item.title} href={item.href!} className="shortcut-card"><item.icon className="size-5" /><span><strong>{item.title}</strong><small>{item.note}</small></span><Plus className="size-4 shortcut-plus" /></Link> : <button key={item.title} onClick={() => openCreate(item.mode, "movementType" in item ? item.movementType : "expense")} className="shortcut-card">
            <item.icon className="size-5" /><span><strong>{item.title}</strong><small>{item.note}</small></span><Plus className="size-4 shortcut-plus" />
          </button>
        ))}
      </section>

      <WorkspaceFilterBar snapshot={data} filters={workspaceFilters} onChange={setWorkspaceFilters} />

      <section className="content-card overflow-hidden">
        <div className="card-title-row"><div><h2>Movimientos recientes</h2><p>{transactions.length} registros manuales en total</p></div><button className="text-link" onClick={() => openCreate("movement")}>Registrar movimiento</button></div>
        {transactions.length === 0 ? <EmptyRecords icon={ReceiptText} title="Todavía no hay movimientos" description="Empieza con un ingreso, gasto o transferencia. Los indicadores del panel se actualizarán con tus registros." action={() => openCreate("movement")} actionLabel="Registrar primer movimiento" /> : (
          <div className="table-wrap"><table><thead><tr><th>Fecha</th><th>Detalle</th><th>Área</th><th>Cuenta</th><th>Importe</th><th></th></tr></thead><tbody>{transactions.slice(0, 16).map(item => {
            const account = accounts.find(accountItem => accountItem.id === item.accountId);
            const category = categories.find(categoryItem => categoryItem.id === item.categoryId);
            const negative = item.type === "expense" || item.type === "transfer_out";
            const entity = data?.entities.find(entityItem => entityItem.id === item.entityId);
            const isTransfer = item.type === "transfer_out" || item.type === "transfer_in";
            const transferGroupId = item.transferGroupId;
            const transferPair = transferGroupId ? (data?.transactions.filter(transaction => transaction.transferGroupId === transferGroupId) ?? []) : [];
            const transferOut = transferPair.find(transaction => transaction.type === "transfer_out");
            const transferIn = transferPair.find(transaction => transaction.type === "transfer_in");
            const isCardPayment = transferPair.some(transaction => transaction.creditCardId && transaction.type === "transfer_in");
            const transferNote = item.notes?.split(" · ").slice(1).join(" · ") ?? "";
            return <tr key={item.id}><td>{formatDate(item.occurredAt, { day: "2-digit", month: "short" })}</td><td><div className="table-main"><span className={`movement-icon type-${item.type}`}>{item.type === "income" || item.type === "transfer_in" ? <ArrowDownLeft className="size-4" /> : <ArrowUpRight className="size-4" />}</span><span><strong>{item.notes || typeLabel[item.type]}</strong><small>{isTransfer ? isCardPayment ? "Pago de tarjeta · Gestionar desde Tarjetas" : `Traspaso entre cuentas propias · ${item.reviewStatus === "pending_review" ? "Pendiente de revisión" : "Aprobado"}` : `${category?.name ?? "Sin categoría"} · ${item.reviewStatus === "pending_review" ? "Pendiente de revisión" : item.reviewStatus === "draft" ? "Borrador" : item.status === "estimated" ? "Estimado" : "Aprobado"}`}{entity ? ` · ${entity.shortCode || entity.name}` : ""}</small></span></div></td><td><ScopePill scope={item.scope} /></td><td>{account?.name ?? "Sin cuenta"}</td><td className={negative ? "amount-negative" : "amount-positive"}>{negative ? "−" : "+"}{formatMoney(item.amountCents, item.currency)}</td><td><div className="row-actions">{isTransfer ? transferGroupId ? <>{isCardPayment ? <Link href="/tarjetas" aria-label="Gestionar pago de tarjeta"><CreditCard className="size-4" /></Link> : <button aria-label="Editar traspaso completo" disabled={!transferOut || !transferIn} onClick={() => { if (!transferOut || !transferIn) return; setMode("transfer"); setEditingTransfer({ transferGroupId, sourceAccountId: transferOut.accountId?.toString() ?? "", destinationAccountId: transferIn.accountId?.toString() ?? "", amount: fromCents(transferOut.amountCents), occurredAt: new Date(transferOut.occurredAt).toISOString().slice(0, 10), status: transferOut.status, notes: transferNote }); setDialogOpen(true); }}><Pencil className="size-4" /></button>}<button aria-label="Eliminar traspaso completo" onClick={() => { if (confirm("¿Eliminar ambas partes de este traspaso entre cuentas?")) removeTransfer.mutate({ transferGroupId }); }}><Trash2 className="size-4" /></button></> : <span className="text-xs text-muted-foreground">Revisar grupo</span> : <><button aria-label="Editar movimiento" onClick={() => { setMode("movement"); setEditingMovement(item); setDialogOpen(true); }}><Pencil className="size-4" /></button><button aria-label="Eliminar movimiento" onClick={() => { if (confirm("¿Eliminar este movimiento manual?")) removeTransaction.mutate({ id: item.id }); }}><Trash2 className="size-4" /></button></>}</div></td></tr>;
          })}</tbody></table></div>)}
      </section>

      <div className="grid xl:grid-cols-2 gap-6">
        <section className="content-card">
          <div className="card-title-row"><div><h2>Cuentas y activos</h2><p>Valores manuales con fecha de valoración.</p></div><button className="icon-text-button" onClick={() => openCreate("account")}><Plus className="size-4" /> Añadir</button></div>
          {accounts.length === 0 ? <EmptyRecords icon={Landmark} title="Sin cuentas ni activos" description="Registra efectivo, cuentas, inversiones, inmuebles o activos empresariales." action={() => openCreate("account")} actionLabel="Añadir cuenta" compact /> : <div className="mini-list">{accounts.map(account => <div className="mini-list-row" key={account.id}><div className="mini-icon"><Landmark className="size-4" /></div><div><strong>{account.name}</strong><small>{account.type} · {account.isLiquid ? "Liquidez inmediata" : "No líquido"}</small></div><div className="mini-value"><strong>{formatMoney(account.currentValueCents, account.currency)}</strong><small>{formatDate(account.valuationDate)}</small></div><div className="row-actions"><button aria-label="Editar cuenta" onClick={() => { setMode("account"); setEditingAccount(account); setDialogOpen(true); }}><Pencil className="size-4" /></button><button aria-label="Eliminar cuenta" onClick={() => { if (confirm("¿Eliminar esta cuenta o activo?") ) removeAccount.mutate({ id: account.id }); }}><Trash2 className="size-4" /></button></div></div>)}</div>}
        </section>
        <section className="content-card">
          <div className="card-title-row"><div><h2>Categorías</h2><p>Clasifica y separa lo personal de lo empresarial.</p></div><button className="icon-text-button" onClick={() => openCreate("category")}><Plus className="size-4" /> Añadir</button></div>
          {categories.length === 0 ? <EmptyRecords icon={FolderPlus} title="Crea tus primeras categorías" description="Las categorías permiten comparar gastos reales y presupuesto." action={() => openCreate("category")} actionLabel="Crear categoría" compact /> : <div className="category-grid">{categories.map(category => <div key={category.id} className="category-token"><span><strong>{category.name}</strong><small>{category.type} · {scopeLabel[category.scope]}</small></span><div className="row-actions"><button aria-label="Editar categoría" onClick={() => { setMode("category"); setEditingCategory(category); setDialogOpen(true); }}><Pencil className="size-4" /></button><button aria-label="Eliminar categoría" onClick={() => { if (confirm("¿Eliminar esta categoría?") ) removeCategory.mutate({ id: category.id }); }}><Trash2 className="size-4" /></button></div></div>)}</div>}
        </section>
      </div>

      <section className="content-card">
        <div className="card-title-row"><div><h2>Documentos de respaldo</h2><p>Registra enlaces seguros, tipo de documento y vencimientos. No se procesan pagos ni datos bancarios.</p></div><button className="icon-text-button" onClick={() => openCreate("document")}><Plus className="size-4" /> Añadir documento</button></div>
        {(scopedData?.documents.length ?? 0) === 0 ? <EmptyRecords icon={Archive} title="Sin documentos para este filtro" description="Ajusta el filtro o guarda el enlace de un contrato, extracto, factura o comprobante." action={() => openCreate("document")} actionLabel="Añadir documento" compact /> : <div className="document-list">{scopedData?.documents.map(document => <div className="mini-list-row" key={document.id}><div className="mini-icon"><FileText className="size-4" /></div><div><strong>{document.name}</strong><small>{document.type} · {scopeLabel[document.scope]} · {document.referenceProvider === "google_drive" ? "Referencia de Google Drive" : document.referenceProvider === "url" ? "URL manual" : "Otra referencia"} · {document.verified ? "Verificado" : "Por verificar"}</small></div>{document.referenceUrl ? <a className="text-link" href={document.referenceUrl} target="_blank" rel="noreferrer">Abrir enlace</a> : <span className="text-muted">Sin enlace</span>}<div className="row-actions"><button aria-label="Editar documento" onClick={() => { setMode("document"); setEditingDocument(document); setDialogOpen(true); }}><Pencil className="size-4" /></button><button aria-label="Eliminar documento" onClick={() => { if (confirm("¿Eliminar este documento?") ) removeDocument.mutate({ id: document.id }); }}><Trash2 className="size-4" /></button></div></div>)}</div>}
      </section>
    </div>
  );
}

function EmptyRecords({ icon: Icon, title, description, action, actionLabel, compact = false }: { icon: typeof Landmark; title: string; description: string; action: () => void; actionLabel: string; compact?: boolean }) {
  return <div className={`empty-state ${compact ? "empty-compact" : ""}`}><div className="empty-icon"><Icon className="size-5" /></div><div><h3>{title}</h3><p>{description}</p>{!compact && <Button variant="outline" className="mt-4" onClick={action}>{actionLabel}</Button>}</div>{compact && <Button variant="outline" onClick={action}>{actionLabel}</Button>}</div>;
}

function MovementForm({ accounts, creditCards, categories, contacts, entities, projects, workspaceAccess, defaultCurrency, initialType, editing, onDone }: { accounts: any[]; creditCards: any[]; categories: any[]; contacts: any[]; entities: any[]; projects: any[]; workspaceAccess: any; defaultCurrency: string; initialType: keyof typeof typeLabel; editing: any; onDone: () => void }) {
  const mutation = trpc.finance.workspace.transactionSave.useMutation({ onSuccess: () => { toast.success(workspaceAccess?.role === "owner" ? "Movimiento guardado y aprobado" : "Borrador enviado a revisión"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState(() => ({ type: editing?.type ?? initialType, scope: editing?.scope ?? "personal", amount: editing ? fromCents(editing.amountCents) : "", currency: editing?.currency ?? defaultCurrency, entityId: editing?.entityId?.toString() ?? "", projectId: editing?.projectId?.toString() ?? "", accountId: editing?.accountId?.toString() ?? "", creditCardId: editing?.creditCardId?.toString() ?? "", categoryId: editing?.categoryId?.toString() ?? "", contactId: editing?.contactId?.toString() ?? "", occurredAt: editing?.occurredAt ? new Date(editing.occurredAt).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10), isEssential: editing?.isEssential ?? false, status: editing?.status ?? "confirmed", incomeNature: editing?.incomeNature ?? "other", exchangeRate: editing?.exchangeRateMicros ? (editing.exchangeRateMicros / 1_000_000).toString() : "", transferGroupId: editing?.transferGroupId ?? "", notes: editing?.notes ?? "" }));
  const submit = (event: FormEvent) => { event.preventDefault(); const rateMicros = form.currency !== defaultCurrency && form.exchangeRate ? Math.round(Number(form.exchangeRate) * 1_000_000) : null; const originalCents = toCents(form.amount); const reportAmountCents = form.currency === defaultCurrency ? originalCents : rateMicros ? Math.round(originalCents * rateMicros / 1_000_000) : null; mutation.mutate({ id: editing?.id, type: form.type, scope: form.scope, amountCents: originalCents, currency: form.currency.toUpperCase(), reportCurrency: defaultCurrency, reportAmountCents, exchangeRateMicros: rateMicros, exchangeRateDate: rateMicros ? new Date(`${form.occurredAt}T12:00:00`).getTime() : null, incomeNature: form.incomeNature, entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, accountId: form.accountId ? Number(form.accountId) : null, creditCardId: form.creditCardId ? Number(form.creditCardId) : null, categoryId: form.categoryId ? Number(form.categoryId) : null, contactId: form.contactId ? Number(form.contactId) : null, occurredAt: new Date(`${form.occurredAt}T12:00:00`).getTime(), isEssential: form.isEssential, status: form.status, transferGroupId: form.transferGroupId || null, notes: form.notes || null }); };
  const isTransfer = form.type.startsWith("transfer");
  const availableProjects = projects.filter(project => !form.entityId || project.entityId === Number(form.entityId));
  return <form className="form-grid" onSubmit={submit}><div className="form-field"><Label>Tipo</Label><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value as any, creditCardId: event.target.value === "expense" ? form.creditCardId : "" })}>{Object.entries(typeLabel).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value as any })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><div className="form-field"><Label>Contacto financiero</Label><select value={form.contactId} onChange={event => setForm({ ...form, contactId: event.target.value })}><option value="">Sin contacto</option>{contacts.filter(contact => contact.status === "active" || contact.id === editing?.contactId).map(contact => <option key={contact.id} value={contact.id}>{contact.name}</option>)}</select></div><div className="form-field"><Label>Entidad</Label><select value={form.entityId} onChange={event => setForm({ ...form, entityId: event.target.value, projectId: "" })}><option value="">Sin entidad / personal</option>{entities.map(entity => <option key={entity.id} value={entity.id}>{entity.shortCode || entity.name}</option>)}</select></div><div className="form-field"><Label>Proyecto</Label><select value={form.projectId} onChange={event => setForm({ ...form, projectId: event.target.value })}><option value="">Sin proyecto</option>{availableProjects.map(project => <option key={project.id} value={project.id}>{project.name}</option>)}</select></div><div className="form-field"><Label>Importe</Label><Input type="number" min="0.01" step="0.01" required value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })} /></div><div className="form-field"><Label>Moneda</Label><Input maxLength={3} required value={form.currency} onChange={event => setForm({ ...form, currency: event.target.value.toUpperCase() })} /></div>{form.currency !== defaultCurrency && <div className="form-field"><Label>Tipo de cambio a {defaultCurrency}</Label><Input type="number" min="0.000001" step="0.000001" required value={form.exchangeRate} onChange={event => setForm({ ...form, exchangeRate: event.target.value })} /><small>Manual y trazable para esta partida.</small></div>}<div className="form-field"><Label>Fecha</Label><Input type="date" required value={form.occurredAt} onChange={event => setForm({ ...form, occurredAt: event.target.value })} /></div>{form.type === "income" && <div className="form-field"><Label>Naturaleza del ingreso</Label><select value={form.incomeNature} onChange={event => setForm({ ...form, incomeNature: event.target.value as any })}><option value="business_revenue">Ingreso de negocio</option><option value="salary_commission">Salario o comisión</option><option value="family_support">Ayuda familiar</option><option value="owner_draw">Retiro o aportación propia</option><option value="other">Otro / por revisar</option></select></div>}<div className="form-field"><Label>Cuenta de efectivo (opcional)</Label><select value={form.accountId} onChange={event => setForm({ ...form, accountId: event.target.value })}><option value="">{form.creditCardId ? "No aplica: gasto cargado a tarjeta" : "Sin cuenta / pendiente"}</option>{accounts.map(account => <option key={account.id} value={account.id}>{account.name}</option>)}</select></div>{form.type === "expense" && creditCards.filter(card => card.status === "active" && card.currency === form.currency).length > 0 ? <div className="form-field"><Label>Tarjeta de crédito (opcional)</Label><select value={form.creditCardId} onChange={event => setForm({ ...form, creditCardId: event.target.value, accountId: event.target.value ? "" : form.accountId })}><option value="">No usar tarjeta</option>{creditCards.filter(card => card.status === "active" && card.currency === form.currency).map(card => <option key={card.id} value={card.id}>{card.name} · saldo {formatMoney(card.balanceCents, card.currency)}</option>)}</select><small>El gasto aumenta el saldo de la tarjeta una sola vez. Su pago posterior se registra como traspaso.</small></div> : null}{!isTransfer && <div className="form-field"><Label>Categoría</Label><select value={form.categoryId} onChange={event => setForm({ ...form, categoryId: event.target.value })}><option value="">Sin categoría / pendiente</option>{categories.filter(category => category.isActive).map(category => <option key={category.id} value={category.id}>{category.name}</option>)}</select></div>}{isTransfer && <div className="form-field"><Label>Grupo de transferencia</Label><Input placeholder="Mismo identificador para entrada y salida" value={form.transferGroupId} onChange={event => setForm({ ...form, transferGroupId: event.target.value })} /></div>}<div className="form-field"><Label>Calidad del dato</Label><select value={form.status} onChange={event => setForm({ ...form, status: event.target.value as any })}><option value="confirmed">Confirmado</option><option value="estimated">Estimado</option><option value="needs_review">Pendiente de revisar</option></select></div><div className="switch-row"><Switch checked={form.isEssential} onCheckedChange={checked => setForm({ ...form, isEssential: checked })} /><span>Gasto esencial</span></div><div className="form-field span-2"><Label>Descripción o nota</Label><Textarea placeholder="Ej. Compra semanal, factura, aclaración" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>{mutation.isPending ? "Guardando…" : workspaceAccess?.role === "owner" ? editing ? "Guardar cambios" : "Guardar y aprobar" : "Enviar a revisión"}</Button></div></form>;
}

function TransferForm({ accounts, investments, workspaceAccess, editing, onDone }: { accounts: any[]; investments: any[]; workspaceAccess: any; editing: any; onDone: () => void }) {
  const createMutation = trpc.finance.workspace.transferSave.useMutation({ onSuccess: () => { toast.success(workspaceAccess?.role === "owner" ? "Traspaso registrado sin afectar ingresos ni gastos" : "Traspaso enviado a revisión"); onDone(); }, onError: error => toast.error(error.message) });
  const updateMutation = trpc.finance.workspace.transferUpdate.useMutation({ onSuccess: () => { toast.success("Traspaso actualizado como un par completo."); onDone(); }, onError: error => toast.error(error.message) });
  const activeAccounts = accounts.filter(account => account.status === "active");
  const [form, setForm] = useState(() => ({ sourceAccountId: editing?.sourceAccountId ?? "", destinationAccountId: editing?.destinationAccountId ?? "", investmentId: "", amount: editing?.amount ?? "", occurredAt: editing?.occurredAt ?? new Date().toISOString().slice(0, 10), status: editing?.status ?? "confirmed", notes: editing?.notes ?? "" }));
  const source = activeAccounts.find(account => account.id === Number(form.sourceAccountId));
  const destination = activeAccounts.find(account => account.id === Number(form.destinationAccountId));
  const compatibleInvestments = investments.filter(investment => investment.status === "active" && (!destination || investment.currency === destination.currency));
  const submit = (event: FormEvent) => { event.preventDefault(); const payload = { sourceAccountId: Number(form.sourceAccountId), destinationAccountId: Number(form.destinationAccountId), amountCents: toCents(form.amount), occurredAt: new Date(`${form.occurredAt}T12:00:00`).getTime(), status: form.status as any, notes: form.notes || null }; if (editing) updateMutation.mutate({ ...payload, transferGroupId: editing.transferGroupId }); else createMutation.mutate({ ...payload, investmentId: form.investmentId ? Number(form.investmentId) : null }); };
  const pending = createMutation.isPending || updateMutation.isPending;
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><div className="rounded-xl border border-primary/15 bg-primary/5 p-3 text-sm text-muted-foreground"><strong className="text-foreground">{editing ? "Edición atómica:" : "Caso Santander → Plata:"}</strong> {editing ? "se actualizan a la vez la salida y la entrada. Los pagos de tarjeta se modifican desde Tarjetas y las aportaciones de inversión desde Ahorro e inversiones." : "crea o selecciona ambas cuentas, registra este traspaso y, si Plata representa una posición de ahorro, vincúlala abajo. Se crea una aportación trazable, pero no un ingreso ni un gasto."}</div></div><div className="form-field"><Label>Cuenta de origen</Label><select required value={form.sourceAccountId} onChange={event => setForm({ ...form, sourceAccountId: event.target.value })}><option value="">Elige la cuenta de salida</option>{activeAccounts.map(account => <option key={account.id} value={account.id}>{account.name} · {account.currency}</option>)}</select></div><div className="form-field"><Label>Cuenta de destino</Label><select required value={form.destinationAccountId} onChange={event => setForm({ ...form, destinationAccountId: event.target.value, investmentId: "" })}><option value="">Elige la cuenta de entrada</option>{activeAccounts.map(account => <option key={account.id} value={account.id} disabled={account.id === Number(form.sourceAccountId)}>{account.name} · {account.currency}</option>)}</select></div>{!editing ? <div className="form-field span-2"><Label>Posición de ahorro o inversión vinculada (opcional)</Label><select value={form.investmentId} onChange={event => setForm({ ...form, investmentId: event.target.value })}><option value="">Sólo traspasar entre cuentas</option>{compatibleInvestments.map(investment => <option key={investment.id} value={investment.id}>{investment.name} · {investment.currency}</option>)}</select><small>Úsalo si el traspaso es una aportación a una posición ya creada. Después confirma su valuación manual para no duplicar patrimonio.</small></div> : null}{source && destination && source.currency !== destination.currency ? <p className="form-field span-2 text-sm text-destructive">Estas cuentas usan monedas distintas. Registra una conversión manual confirmada por separado si aplica.</p> : null}<div className="form-field"><Label>Importe{source ? ` (${source.currency})` : ""}</Label><Input type="number" min="0.01" step="0.01" required value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })} /></div><div className="form-field"><Label>Fecha</Label><Input type="date" required value={form.occurredAt} onChange={event => setForm({ ...form, occurredAt: event.target.value })} /></div><div className="form-field"><Label>Calidad del dato</Label><select value={form.status} onChange={event => setForm({ ...form, status: event.target.value })}><option value="confirmed">Confirmado</option><option value="estimated">Estimado</option><option value="needs_review">Pendiente de revisar</option></select></div><div className="form-field span-2"><Label>Nota opcional</Label><Textarea placeholder="Ej. Fondeo de Plata desde Santander" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={pending || Boolean(source && destination && source.currency !== destination.currency) || activeAccounts.length < 2}>{pending ? "Guardando…" : editing ? "Guardar traspaso" : workspaceAccess?.role === "owner" ? "Registrar traspaso" : "Enviar a revisión"}</Button></div></form>;
}

function AccountForm({ entities, projects, defaultCurrency, editing, onDone }: { entities: any[]; projects: any[]; defaultCurrency: string; editing: any; onDone: () => void }) {
  const mutation = trpc.finance.accounts.save.useMutation({ onSuccess: () => { toast.success("Cuenta o activo guardado"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState(() => ({ name: editing?.name ?? "", type: editing?.type ?? "bank", scope: editing?.scope ?? "personal", entityId: editing?.entityId?.toString() ?? "", projectId: editing?.projectId?.toString() ?? "", value: editing ? fromCents(editing.currentValueCents) : "", currency: editing?.currency ?? defaultCurrency, isLiquid: editing?.isLiquid ?? true, valuationDate: editing?.valuationDate ? new Date(editing.valuationDate).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10), status: editing?.status ?? "active", notes: editing?.notes ?? "" }));
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ id: editing?.id, entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, name: form.name, type: form.type, scope: form.scope, currentValueCents: toCents(form.value), currency: form.currency.toUpperCase(), isLiquid: form.isLiquid, valuationDate: form.valuationDate ? new Date(`${form.valuationDate}T12:00:00`).getTime() : null, status: form.status, notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><Label>Nombre</Label><Input required placeholder="Ej. Cuenta operativa, fondo de emergencia" value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></div><div className="form-field"><Label>Tipo</Label><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value as any })}><option value="cash">Efectivo</option><option value="bank">Cuenta bancaria</option><option value="investment">Inversión</option><option value="pension">Pensión</option><option value="property">Inmueble</option><option value="business">Empresa</option><option value="other">Otro</option></select></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value as any })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><div className="form-field"><Label>Valor actual</Label><Input type="number" min="0" step="0.01" required value={form.value} onChange={event => setForm({ ...form, value: event.target.value })} /></div><div className="form-field"><Label>Moneda</Label><Input maxLength={3} required value={form.currency} onChange={event => setForm({ ...form, currency: event.target.value.toUpperCase() })} /></div><div className="form-field"><Label>Fecha de valoración</Label><Input type="date" value={form.valuationDate} onChange={event => setForm({ ...form, valuationDate: event.target.value })} /></div><div className="form-field"><Label>Estado</Label><select value={form.status} onChange={event => setForm({ ...form, status: event.target.value as any })}><option value="active">Activa</option><option value="closed">Cerrada</option></select></div><div className="switch-row"><Switch checked={form.isLiquid} onCheckedChange={checked => setForm({ ...form, isLiquid: checked })} /><span>Disponible como liquidez</span></div><div className="form-field span-2"><Label>Notas</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>{mutation.isPending ? "Guardando…" : "Guardar cuenta o activo"}</Button></div></form>;
}

function CategoryForm({ editing, onDone }: { editing: any; onDone: () => void }) {
  const mutation = trpc.finance.categories.save.useMutation({ onSuccess: () => { toast.success("Categoría guardada"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState(() => ({ name: editing?.name ?? "", type: editing?.type ?? "expense", scope: editing?.scope ?? "personal", isEssential: editing?.isEssential ?? false, isActive: editing?.isActive ?? true }));
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ id: editing?.id, ...form } as any); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><Label>Nombre de la categoría</Label><Input required placeholder="Ej. Alimentación, clientes, impuestos" value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></div><div className="form-field"><Label>Tipo</Label><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value })}><option value="income">Ingreso</option><option value="expense">Gasto</option><option value="transfer">Transferencia</option><option value="mixed">Mixta</option></select></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><div className="switch-row span-2"><Switch checked={form.isEssential} onCheckedChange={checked => setForm({ ...form, isEssential: checked })} /><span>Esta categoría es esencial</span></div><div className="switch-row span-2"><Switch checked={form.isActive} onCheckedChange={checked => setForm({ ...form, isActive: checked })} /><span>Categoría disponible para nuevos registros</span></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>Guardar categoría</Button></div></form>;
}

function DocumentForm({ accounts, debts, entities, projects, editing, onDone }: { accounts: any[]; debts: any[]; entities: any[]; projects: any[]; editing: any; onDone: () => void }) {
  const mutation = trpc.finance.documents.save.useMutation({ onSuccess: () => { toast.success("Documento registrado"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState(() => ({ name: editing?.name ?? "", type: editing?.type ?? "receipt", documentClass: editing?.documentClass ?? "general", scope: editing?.scope ?? "personal", entityId: editing?.entityId?.toString() ?? "", projectId: editing?.projectId?.toString() ?? "", relatedEntityType: editing?.relatedEntityType ?? "none", relatedEntityId: editing?.relatedEntityId?.toString() ?? "", jurisdiction: editing?.jurisdiction ?? "", referenceUrl: editing?.referenceUrl ?? "", referenceProvider: editing?.referenceProvider ?? "google_drive", issuedAt: editing?.issuedAt ? new Date(editing.issuedAt).toISOString().slice(0, 10) : "", expiresAt: editing?.expiresAt ? new Date(editing.expiresAt).toISOString().slice(0, 10) : "", reminderAt: editing?.reminderAt ? new Date(editing.reminderAt).toISOString().slice(0, 10) : "", verified: editing?.verified ?? false, notes: editing?.notes ?? "" }));
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ id: editing?.id, ...form, entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, relatedEntityId: form.relatedEntityId ? Number(form.relatedEntityId) : null, issuedAt: form.issuedAt ? new Date(`${form.issuedAt}T12:00:00`).getTime() : null, expiresAt: form.expiresAt ? new Date(`${form.expiresAt}T12:00:00`).getTime() : null, reminderAt: form.reminderAt ? new Date(`${form.reminderAt}T12:00:00`).getTime() : null, jurisdiction: form.jurisdiction || null, referenceUrl: form.referenceUrl || null, notes: form.notes || null } as any); };
  const relatedOptions = form.relatedEntityType === "asset" ? accounts : form.relatedEntityType === "debt" ? debts : [];
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><Label>Nombre</Label><Input required placeholder="Ej. Póliza de seguro, testamento o título de propiedad" value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></div><div className="form-field"><Label>Tipo</Label><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value })}><option value="statement">Extracto</option><option value="invoice">Factura</option><option value="contract">Contrato</option><option value="policy">Póliza</option><option value="tax">Fiscal</option><option value="receipt">Comprobante</option><option value="other">Otro</option></select></div><div className="form-field"><Label>Clasificación</Label><select value={form.documentClass} onChange={event => setForm({ ...form, documentClass: event.target.value })}><option value="general">General</option><option value="identity_residency">Identidad o residencia</option><option value="tax_residency">Residencia fiscal</option><option value="tax_filing">Declaración u obligación fiscal</option><option value="insurance">Seguro</option><option value="will_estate">Testamento o sucesión</option><option value="property">Propiedad o inmueble</option><option value="investment_instrument">Instrumento de inversión</option><option value="loan_credit">Crédito o préstamo</option><option value="legal_contract">Contrato legal</option></select></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><div className="form-field"><Label>Relación financiera</Label><select value={form.relatedEntityType} onChange={event => setForm({ ...form, relatedEntityType: event.target.value, relatedEntityId: "" })}><option value="none">Sin relación</option><option value="asset">Activo o propiedad</option><option value="debt">Deuda</option><option value="insurance">Seguro</option><option value="tax">Obligación fiscal</option><option value="estate">Patrimonio o sucesión</option></select></div>{relatedOptions.length > 0 ? <div className="form-field"><Label>{form.relatedEntityType === "asset" ? "Activo relacionado" : "Deuda relacionada"}</Label><select value={form.relatedEntityId} onChange={event => setForm({ ...form, relatedEntityId: event.target.value })}><option value="">Sin vínculo específico</option>{relatedOptions.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></div> : <div className="form-field"><Label>País o jurisdicción</Label><Input placeholder="Ej. México" value={form.jurisdiction} onChange={event => setForm({ ...form, jurisdiction: event.target.value })} /></div>}<div className="form-field span-2"><Label>URL segura de referencia</Label><Input type="url" placeholder="https://…" value={form.referenceUrl} onChange={event => setForm({ ...form, referenceUrl: event.target.value })} /><small>La URL se guarda como referencia; Meximoney no copia archivos ni solicita acceso al proveedor.</small></div><div className="form-field"><Label>Proveedor de la referencia</Label><select value={form.referenceProvider} onChange={event => setForm({ ...form, referenceProvider: event.target.value })}><option value="google_drive">Google Drive (enlace manual)</option><option value="url">Otro enlace web</option><option value="other">Otra referencia</option></select></div><div className="form-field"><Label>Fecha de emisión</Label><Input type="date" value={form.issuedAt} onChange={event => setForm({ ...form, issuedAt: event.target.value })} /></div><div className="form-field"><Label>Vencimiento</Label><Input type="date" value={form.expiresAt} onChange={event => setForm({ ...form, expiresAt: event.target.value })} /></div><div className="form-field"><Label>Recordatorio manual</Label><Input type="date" value={form.reminderAt} onChange={event => setForm({ ...form, reminderAt: event.target.value })} /></div><div className="switch-row span-2"><Switch checked={form.verified} onCheckedChange={checked => setForm({ ...form, verified: checked })} /><span>Documento revisado y verificado</span></div><div className="form-field span-2"><Label>Notas</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>Registrar documento</Button></div></form>;
}
